import { Mesh, PlaneGeometry, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string[]} textContent
 * @property {{[key:string]:string}} colors
 * @property {Object} assets
 * @property {{width:number,height:number,x:number,y:number}} atlasRegion
 */

/**
 * @typedef {Object} NodeContext
 * @property {{load: (url:string)=>import('three').Texture}} textureLoader
 * @property {{generateTexture: (text:string, opts:any)=>import('three').Texture}} fontAtlas
 * @property {{[key:string]: (obj:THREE.Object3D, params:any)=>void}} primitives
 */

/**
 * Creates a pricing‑card label node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // -------------------------------------------------------------------------
  // Geometry
  // -------------------------------------------------------------------------
  const aspect = config.atlasRegion?.height
    ? config.atlasRegion.height / config.atlasRegion.width
    : 320 / 512; // fallback
  const planeGeom = new PlaneGeometry(1, aspect);

  // -------------------------------------------------------------------------
  // Base texture (decorative image)
  // -------------------------------------------------------------------------
  const baseTex = ctx.textureLoader.load(
    '/prism-mock/home/nodes/orb-decor.png'
  );
  const baseMat = new MeshBasicNodeMaterial();
  baseMat.colorNode = texture(baseTex);
  baseMat.transparent = true;
  const baseMesh = new Mesh(planeGeom, baseMat);
  baseMesh.castShadow = false;
  baseMesh.receiveShadow = false;

  // -------------------------------------------------------------------------
  // Text overlay using the font atlas
  // -------------------------------------------------------------------------
  const label = (config.textContent && config.textContent[0]) || '';
  const textTex = ctx.fontAtlas.generateTexture(label, {
    // basic typographic hints – the concrete implementation of generateTexture
    // is delegated to the host; we only pass a sensible descriptor.
    fontFamily: 'Lora',
    fontWeight: 400,
    // using the headline scene‑unit height from the design tokens
    // (0.34 scene‑units ≈ 34 px at a 100 px = 1 scene‑unit reference)
    fontSize: 0.34,
    color: config.colors?.ink ?? '#16161d',
    // atlas placement hint – matches the supplied source rect
    atlasIndex: 0,
    sourceRect: {
      x: 0,
      y: 0,
      width: config.atlasRegion?.width ?? 512,
      height: config.atlasRegion?.height ?? 320,
    },
  });

  const textMat = new MeshBasicNodeMaterial();
  textMat.colorNode = texture(textTex);
  textMat.transparent = true;
  const textMesh = new Mesh(planeGeom.clone(), textMat);
  textMesh.castShadow = false;
  textMesh.receiveShadow = false;

  // -------------------------------------------------------------------------
  // Container object
  // -------------------------------------------------------------------------
  const container = new Object3D();
  container.add(baseMesh);
  container.add(textMesh);

  // Position / rotation / scale from the specification
  container.position.set(-3.2, 1, 0.06);
  container.rotation.set(0, 0, 0);
  container.scale.set(1, 1, 1);

  // -------------------------------------------------------------------------
  // User data – event handlers placeholder & cleanup logic
  // -------------------------------------------------------------------------
  container.userData.handlers = {};

  // Store any GSAP timelines that might be created later (none now)
  const _timelines = [];

  container.userData.cleanup = () => {
    // Dispose textures
    if (baseTex) baseTex.dispose();
    if (textTex) textTex.dispose();

    // Dispose materials
    if (baseMat) baseMat.dispose();
    if (textMat) textMat.dispose();

    // Dispose geometry
    if (planeGeom) planeGeom.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();

    // Kill GSAP animations
    _timelines.forEach((tl) => tl.kill());
  };

  // -------------------------------------------------------------------------
  // Apply cinematic primitives if any (none for this node)
  // -------------------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(container, prim.params);
      }
    });
  }

  return container;
}
